// Embedded in the n8n Code node; no network calls or message delivery here.
const response = $input.first().json;
const escapeHtml = (value, limit = 200) => String(value ?? '').slice(0, limit)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const output = (report, status) => [{ json: { report, status, part: 1, parts: 1 } }];
const failure = (reason) => output(
  '⚠️ <b>Laporan Presensi Tahsin Bapak Wali Santri</b>\n\n' + reason +
  '\nStatus pengisian belum dapat dipastikan. Periksa aplikasi dan execution n8n.\n' +
  'https://tahsin.griyaquran.web.id/pantau-input.php', 'error');

if (!response || typeof response !== 'object' || response.error) {
  return failure('API tidak dapat dihubungi atau responsnya bukan JSON yang valid.');
}
const httpStatus = Number(response.statusCode ?? 200);
if (!Number.isFinite(httpStatus) || httpStatus < 200 || httpStatus >= 300) {
  return failure('API mengembalikan HTTP ' + (Number.isFinite(httpStatus) ? httpStatus : 'tidak valid') + '.');
}
const body = response.body ?? response;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return failure('Format respons API tidak sesuai.');
}
if (body.status === 'skip') {
  return output('ℹ️ <b>Laporan Presensi Tahsin Bapak Wali Santri</b>\n\nPemeriksaan dilewati oleh aplikasi: ' +
    escapeHtml(body.reason || 'Tidak ada pemeriksaan pada jadwal ini.') +
    '\nStatus ini tidak berarti semua presensi lengkap.', 'skip');
}
const asCount = (value) => (typeof value === 'number' || (typeof value === 'string' && /^\d+$/.test(value))) &&
  Number.isSafeInteger(Number(value)) && Number(value) >= 0 ? Number(value) : null;
if (body.status !== 'success' || !Array.isArray(body.data) || asCount(body.count) !== body.data.length) {
  return failure('Respons API tidak memuat daftar kekurangan yang valid.');
}
const summary = body.summary;
if (!summary || asCount(summary.checked_participant_sessions) === null ||
  asCount(summary.complete_participant_sessions) === null || !summary.attendance_counts ||
  !['current_roster', 'session_history', 'unavailable'].includes(summary.roster_basis)) {
  return failure('API belum menyediakan bukti pemeriksaan roster pekan ini. Deploy perbaikan aplikasi sebelum memakai workflow ini; daftar kosong dari API lama bukan bukti semua guru sudah mengisi.');
}
if (body.inspection_complete !== true || Number(summary.checked_participant_sessions) === 0 ||
  Number(summary.complete_participant_sessions) > Number(summary.checked_participant_sessions) ||
  ['H','S','I','A'].some(status => asCount(summary.attendance_counts[status]) === null)) {
  return failure('Roster pekan ini belum dapat diperiksa secara lengkap.');
}
const countFields = ['total_anggota', 'sudah_diisi', 'complete_input', 'belum_diisi',
  'missing_presensi', 'missing_capaian', 'missing_keterangan', 'conflicts'];
const seenGroups = new Set();
const groups = [];
for (const row of body.data) {
  if (!row || typeof row !== 'object' || !/^\d{4}-\d{2}-\d{2}$/.test(row.tanggal_tahsin || '') ||
    asCount(row.ustadz_id) === null || asCount(row.halaqoh_id) === null ||
    row.has_expected_roster !== true || !(row.data_verified === true ||
      (row.data_verified === false && row.roster_basis === 'current_roster' && row.tanggal_tahsin === body.tanggal_tahsin)) ||
    countFields.some((field) => asCount(row[field]) === null)) {
    return failure('Detail guru atau histori roster pada respons API belum sesuai dengan aplikasi.');
  }
  const group = { ...row };
  for (const field of countFields) group[field] = Number(row[field]);
  const key = [row.tanggal_tahsin, row.halaqoh_id, row.ustadz_id].join(':');
  if (seenGroups.has(key) || group.belum_diisi === 0 ||
    group.complete_input + group.belum_diisi !== group.total_anggota ||
    group.sudah_diisi > group.total_anggota ||
    group.missing_presensi + group.missing_capaian + group.missing_keterangan + group.conflicts !== group.belum_diisi) {
    return failure('Jumlah kekurangan pada respons API tidak konsisten.');
  }
  seenGroups.add(key);
  groups.push(group);
}

groups.sort((a, b) => String(a.ustadz_name).localeCompare(String(b.ustadz_name), 'id') ||
  a.tanggal_tahsin.localeCompare(b.tanggal_tahsin) || String(a.nama_halaqoh).localeCompare(String(b.nama_halaqoh), 'id'));
const teacherIds = new Set(groups.map((g) => Number(g.ustadz_id)).filter((id) => id > 0));
const unknownGroups = groups.filter((g) => Number(g.ustadz_id) === 0).length;
const totals = Object.fromEntries(['missing_presensi', 'missing_capaian', 'missing_keterangan', 'conflicts', 'belum_diisi']
  .map((field) => [field, groups.reduce((sum, group) => sum + group[field], 0)]));
const currentPending = groups.filter(g => g.tanggal_tahsin === body.tanggal_tahsin).reduce((sum,g) => sum + g.belum_diisi, 0);
if (Number(summary.complete_participant_sessions) + currentPending !== Number(summary.checked_participant_sessions)) {
  return failure('Jumlah peserta lengkap dan kekurangan tidak sesuai dengan roster yang diperiksa.');
}
const header = '📊 <b>Laporan Presensi Tahsin Bapak Wali Santri</b>\n' +
  'Diperiksa: ' + escapeHtml(body.day) + ', ' + escapeHtml(body.date_today || body.date) + '\n' +
  'Sesi tahsin: ' + escapeHtml(body.tanggal_tahsin_formatted || body.tanggal_tahsin) + '\n' +
  'Peserta-sesi diperiksa: ' + summary.checked_participant_sessions + '; lengkap: ' + summary.complete_participant_sessions + '\n' +
  'Status setelah pemeriksaan: H ' + summary.attendance_counts.H + ' · S ' + summary.attendance_counts.S +
  ' · I ' + summary.attendance_counts.I + ' · Alfa ' + summary.attendance_counts.A + '\n' +
  'Dasar: ' + (summary.roster_basis === 'current_roster' ? 'roster aktif pekan ini (histori belum tersedia)' : 'histori roster sesi') + '.';
const blocks = [header];
if (summary.raw_status_counts && asCount(summary.raw_status_counts.A) !== null && Number(summary.raw_status_counts.A) !== Number(summary.attendance_counts.A)) {
  blocks.push('Catatan Alfa tersimpan: ' + summary.raw_status_counts.A + '. Setelah pemeriksaan: ' +
    summary.attendance_counts.A + '; periksa konflik atau penempatan ganda pada rincian.');
}
if (groups.length === 0) {
  blocks.push('✅ Seluruh peserta pada roster yang diperiksa sudah memiliki presensi lengkap, termasuk status Alfa yang disimpan.');
} else {
  blocks.push('Guru teridentifikasi dengan kekurangan: <b>' + teacherIds.size + '</b>\n' +
    'Kelompok-sesi perlu dilengkapi: ' + groups.length + '\n' +
    'Belum input presensi: ' + totals.missing_presensi + ' peserta-sesi\n' +
    'Capaian belum lengkap: ' + totals.missing_capaian + ' peserta-sesi\n' +
    'Keterangan S/I belum lengkap: ' + totals.missing_keterangan + ' peserta-sesi\n' +
    'Konflik/perlu verifikasi: ' + totals.conflicts + ' peserta-sesi' +
    (unknownGroups ? '\n⚠️ Guru belum ditentukan pada ' + unknownGroups + ' kelompok-sesi.' : ''));
  groups.forEach((group, index) => {
    const reasons = [];
    if (group.missing_presensi) reasons.push('Belum input presensi: ' + group.missing_presensi);
    if (group.missing_capaian) reasons.push('Capaian belum lengkap: ' + group.missing_capaian);
    if (group.missing_keterangan) reasons.push('Keterangan S/I belum lengkap: ' + group.missing_keterangan);
    if (group.conflicts) reasons.push('Konflik/perlu verifikasi: ' + group.conflicts);
    blocks.push((index + 1) + '. <b>' + escapeHtml(group.ustadz_name || 'Guru belum ditentukan', 100) + '</b>\n' +
      'Halaqoh: ' + escapeHtml(group.nama_halaqoh, 100) + '\n' +
      'Sesi: ' + escapeHtml(group.tanggal_tahsin_formatted || group.tanggal_tahsin, 40) + '\n' +
      (group.missing_presensi + group.missing_capaian + group.missing_keterangan === 0 && group.conflicts > 0
        ? '⚠️ Catatan/penempatan perlu verifikasi admin\n'
        : (group.sudah_diisi === 0 ? '🔴 Belum mengisi sama sekali\n' : '🟡 Sudah mengisi, masih perlu dilengkapi\n')) +
      'Lengkap: ' + group.complete_input + '/' + group.total_anggota + ' peserta; perlu dilengkapi: ' + group.belum_diisi + '\n' +
      reasons.join('\n') + '\nBatas input: ' + escapeHtml(group.deadline_at, 32) + ' WIB' +
      (!/^62\d{8,13}$/.test(String(group.ustadz_phone || '')) ? '\n⚠️ Nomor WhatsApp guru belum valid; perlu ditindaklanjuti admin.' : ''));
  });
}
blocks.push('Angka peserta-sesi menghitung satu wali pada satu sesi; satu guru dapat muncul pada beberapa halaqoh/sesi.\n' +
  'Draft kosong tetap belum diinput. Alfa otomatis hanya saat guru menekan finalisasi setelah sesi selesai.\n' +
  'Pengingat WhatsApp ke guru akan dicoba setelah laporan ini; status pengiriman tersedia di execution n8n.\n' +
  'Rincian:\nhttps://tahsin.griyaquran.web.id/pantau-input.php');

// Keep complete HTML blocks together; reserve room for a continuation label.
const chunks = [];
let chunk = '';
for (const block of blocks) {
  if (chunk && chunk.length + block.length + 2 > 3400) {
    chunks.push(chunk);
    chunk = '';
  }
  chunk += (chunk ? '\n\n' : '') + block;
}
if (chunk) chunks.push(chunk);
return chunks.map((report, index) => ({ json: {
  report: (chunks.length > 1 ? 'Bagian ' + (index + 1) + '/' + chunks.length + '\n\n' : '') + report,
  status: groups.length ? 'pending' : 'complete',
  part: index + 1, parts: chunks.length, teacher_count: teacherIds.size,
  group_session_count: groups.length, totals,
} }));

const report = $('Susun Laporan Admin').first().json;
if (report.status !== 'pending') return [];
const response = $('Ambil Kekurangan Presensi').first().json;
const body = response.body ?? response;
if (body.status !== 'success' || body.inspection_complete !== true || !Array.isArray(body.data)) return [];
return body.data.filter(g => Number(g.ustadz_id) > 0 && Number(g.missing_presensi) + Number(g.missing_capaian) + Number(g.missing_keterangan) > 0 && /^62\d{8,13}$/.test(String(g.ustadz_phone || '')))
  .map(g => ({json:{...g,wa_message:'Assalamualaikum Ustadz ' + g.ustadz_name + ',

Mohon melengkapi presensi dan capaian Tahsin Bapak kelompok ' + g.nama_halaqoh + ' untuk sesi ' + g.tanggal_tahsin_formatted + '.

' +
    (Number(g.sudah_diisi) === 0 ? 'Belum ada presensi yang disimpan.
' : 'Presensi sudah diisi sebagian.
') +
    'Lengkap: ' + g.complete_input + '/' + g.total_anggota + ' peserta.
Belum presensi: ' + g.missing_presensi + '; belum capaian: ' + g.missing_capaian + '; belum keterangan S/I: ' + g.missing_keterangan + '; perlu verifikasi: ' + g.conflicts + '.

' +
    'Untuk peserta yang tidak hadir, finalisasi setelah sesi selesai akan menyimpan pilihan kosong sebagai Alfa. Hadir tetap wajib dilengkapi capaian.

https://tahsin.griyaquran.web.id/ustadz/form-presensi.php?id=' + g.halaqoh_id + '&tanggal=' + g.tanggal_tahsin + '

Jazakumullah khairan.'}}));

const failed = $input.all().filter(item => item.json.error);
if (!failed.length) return [];
return [{json:{report:'⚠️ <b>Pengingat WhatsApp Tahsin</b>\n\nAda ' + failed.length + ' error pada node pengiriman guru. Daftar kekurangan tetap ada pada laporan sebelumnya. Periksa execution n8n untuk tindak lanjut.'}}];
